// GPS auto-dispatch: pick the nearest active washer to the customer's area.
// 'Active' means their location doc was updated within the last 30 minutes.

// Approximate centre-point coordinates for each service area (Paschim Vihar, Delhi).
const AREA_COORDS = {
  'GH-9 Paschim Vihar':    {lat: 28.6680, lng: 77.0989},
  'GH-6 Paschim Vihar':    {lat: 28.6695, lng: 77.0970},
  'GH-14 Paschim Vihar':   {lat: 28.6705, lng: 77.0982},
  'Meera Bagh':             {lat: 28.6720, lng: 77.1065},
  'Sundar Vihar':           {lat: 28.6710, lng: 77.1110},
  'Guru Hari Apartments':   {lat: 28.6650, lng: 77.0960},
};

function haversine(lat1, lng1, lat2, lng2) {
  const R = 6371000; // metres
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLng = (lng2 - lng1) * Math.PI / 180;
  const a = Math.sin(dLat/2)**2 +
    Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLng/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

// Webhook body: {doc_id, area}
const body = $('Dispatch maango (webhook)').first().json.body || {};
const docId = String(body.doc_id || '');
const area  = String(body.area  || '');

if (!docId) return [{json: {ok: false, error: 'doc_id missing'}}];

// All location docs read by the Firestore node.
const now = Date.now();
const STALE_MS = 30 * 60 * 1000; // 30 min

const active = $input.all()
  .map(i => i.json)
  .filter(loc => {
    if (!loc.washer_id || !loc.lat || !loc.lng) return false;
    // updated_at is an IST ISO string like "2026-10-18T06:42:00+05:30"
    const age = now - new Date(loc.updated_at).getTime();
    return age <= STALE_MS;
  });

if (!active.length) {
  // No washer is broadcasting GPS — leave washer_id blank so both get the job alert.
  return [{json: {ok: true, assigned: false, reason: 'no_active_washers', doc_id: docId}}];
}

const target = AREA_COORDS[area];
if (!target) {
  // Unknown area — pick the washer with the most recent location update.
  active.sort((a, b) => new Date(b.updated_at) - new Date(a.updated_at));
  return [{json: {ok: true, assigned: true, washer_id: active[0].washer_id, doc_id: docId, method: 'newest'}}];
}

// Nearest active washer by Haversine distance.
let best = null, bestDist = Infinity;
for (const loc of active) {
  const d = haversine(loc.lat, loc.lng, target.lat, target.lng);
  if (d < bestDist) { bestDist = d; best = loc; }
}

return [{json: {ok: true, assigned: !!best, washer_id: best ? best.washer_id : null, doc_id: docId, dist_m: Math.round(bestDist), method: 'nearest'}}];
